using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;

public enum TreatyDefenseAction { Arrange,Dispatch,Refuse,Arrive,Recall,Return,Cancel,Resend }
public enum TreatyDefensePaperKind { Ask,Dispatched,Refused,Arrived,Returning,Returned,Cancel }
public sealed record TreatyDefenseInput(EntityId Id,TreatyDefenseAction Action,EntityId Request,int DutySeconds=0,string? Original=null);
public sealed record TreatyDefenseTerms(EntityId Root,EntityId Aid,EntityId Agreement,EntityId Commander,EntityId Owner,EntityId Source,EntityId Recipient,EntityId Destination,EntityId Muster,int Soldiers,int DutySeconds,int CarryDays,long Until,long At,long Revision,FactionStanceAuthority Authority);
public sealed record TreatyDefenseEntry(TreatyDefenseInput Input,EntityId Root,EntityId Actor,long At,long Revision,TreatyDefenseTerms? Terms,string Paper){public string? Reason{get;init;}}
public sealed record TreatyDefensePaper(string Id,TreatyDefensePaperKind Kind,EntityId Root,EntityId Sender,EntityId Recipient,EntityId Address,long At,long Revision,long Deadline,TreatyDefenseTerms? Terms,long ObservedAt,string? CopyOf){public string? Reason{get;init;}}
public sealed record TreatyDefenseState(int Schema,string Policy,TreatyDefenseEntry[] Entries,TreatyDefensePaper[] Papers,FactionNoticeOpening[] Openings,FactionNoticeOpening[] Failures);
public sealed record TreatyDefenseCard(EntityId Root,string Status,TreatyDefenseTerms? KnownTerms,long? ObservedAt,bool CanCancel);

// Opt-in, physical, source-owned defense assistance. Old saves never acquire new armies on load.
public static class TreatyDefense
{
    public const string Policy="signed-owned-garrison-defense-physical-reports-stock-backed-seven-day-bound-v1",Kind="treaty-physical-defense";
    const long Day=86400;
    static readonly TreatyDefenseState Empty=new(1,Policy,[],[],[],[]);
    static TreatyDefenseState State(ContractWorld w)=>w.Treaties?.Defense??Empty;
    static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool ok,string reason){if(!ok)throw new InvalidDataException(reason);}
    static bool Before(long t,long r,long at,long rev)=>t<at||t==at&&r<rev;
    static string Hash(string s)=>ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(s));
    static string PaperId(EntityId id)=>"message:treaty-defense/"+Hash(id.Value);
    static EntityId Auto(EntityId root,TreatyDefenseAction action)=>new("request:treaty-defense/"+Hash(root.Value)+"/"+action);
    static TreatyDefenseEntry[] Entries(ContractWorld w,long at,long rev)=>State(w).Entries.Where(e=>Before(e.At,e.Revision,at,rev)).ToArray();
    static TreatyDefenseEntry Arrange(ContractWorld w,EntityId root)=>State(w).Entries.Single(e=>e.Input.Id==root&&e.Input.Action==TreatyDefenseAction.Arrange);
    static TreatyOperationPaper Aid(ContractWorld w,EntityId root)=>w.Treaties!.Operations.Single(p=>p.Input.Id==Arrange(w,root).Input.Request);
    static TreatyDefenseTerms? Terms(ContractWorld w,EntityId root,long at=long.MaxValue,long rev=long.MaxValue)=>Entries(w,at,rev).SingleOrDefault(e=>e.Root==root&&e.Input.Action==TreatyDefenseAction.Dispatch)?.Terms;
    static bool Local(ContractWorld w,EntityId actor,EntityId site,long at,long rev)=>TransportWork.At(w,actor,site,at,rev,true);
    static bool Opened(ContractWorld w,string id,EntityId actor,long at,long rev)=>State(w).Openings.Any(o=>o.Message==id&&o.Actor==actor&&Before(o.At,o.Revision,at,rev));
    static bool Cancelled(ContractWorld w,EntityId root,long at,long rev)=>State(w).Papers.Any(p=>p.Root==root&&p.Kind==TreatyDefensePaperKind.Cancel&&Opened(w,p.Id,p.Recipient,at,rev));
    public static bool OwnIdUsed(ContractWorld w,EntityId id)=>State(w).Entries.Any(e=>e.Input.Id==id);
    internal static long CarryCapacity(ContractWorld w,NpcArmyMuster m)=>State(w).Entries.SingleOrDefault(e=>e.Terms?.Muster==m.Id&&e.Input.Action==TreatyDefenseAction.Dispatch)?.Terms is {} t?checked(100L*t.CarryDays*Day):NewGameMilitary.Capacity;
    internal static bool IsMuster(ContractWorld w,NpcArmyMuster m)=>State(w).Entries.Any(e=>e.Input.Action==TreatyDefenseAction.Dispatch&&e.Terms?.Muster==m.Id);
    internal static EntityId Custodian(ContractWorld w,NpcArmyMuster m,long at,long rev)=>IsMuster(w,m)?HouseSuccession.Head(w,m.Owner,at,rev):m.Commander;
    static bool ActiveTask(ContractWorld w,EntityId actor,long at,long rev)=>w.Requests.Any(r=>r.Intent.Executor==actor&&Before(r.CreatedAt,r.CommitSequence,at,rev)&&w.Tasks.Any(t=>t.RequestId==r.Id&&(t.FinishedAt==null||t.FinishedAt>at)));
    static TreatyDefenseTerms? Candidate(ContractWorld w,TreatyDefenseEntry a,EntityId actor,long at,long rev,out string? reason)
    {
        reason=null;try{
            var p=Aid(w,a.Root);var auth=FactionStances.ResolveAuthority(w,actor,p.Input.Target,at,rev-1);
            Need(actor!=w.PlayerControl&&actor==p.Recipient&&p.Intent.Amount==100&&auth!=null&&Local(w,actor,auth.Home,at,rev)&&RegionalDomains.Authority(w,actor,auth.Home,at,rev)&&w.Characters.Single(c=>c.Id==actor).WillObey,"現地の実権・同意・希望兵数を満たしません");
            Need(!PrivateStanddown.ShouldWait(w,actor,at,rev)&&TreatyNegotiations.ClauseUsable(w,actor,p.Input.Acceptance,TreatyClause.Defense,at,rev-1)&&!Cancelled(w,a.Root,at,rev),"本人が知る防衛条項・出撃見合わせ・取消を確認してください");
            long until=Math.Min(p.Terms.Until,a.At+14*Day);Need(at<=until&&!ActiveTask(w,actor,at,rev),"手配期限または他の任務を確認してください");
            Need(!NpcArmies.Musters(w).Any(m=>Before(m.At,m.Revision,at,rev)&&(m.Commander==actor||m.Owner==p.Input.Target&&m.Site==auth!.Home))&&!NewGameMilitary.LedgerStates(w).Any(s=>s.Terms.Owner==p.Input.Target&&s.Terms.Site==auth!.Home),"元の駐屯兵は別の軍務に割り当て済みです");
            var historical=w.ForkTransportLocation();historical.ElapsedSeconds=at;historical.CommitSequence=rev-1;historical.Evidence=w.Evidence.Where(e=>e.RecordedAt<=at).ToArray();historical.Knowledge=w.Knowledge.Where(k=>k.LearnedAt<=at&&historical.Evidence.Any(e=>e.Id==k.Evidence)).ToArray();var origin=NewGameWorld.Node(auth!.Home.Value);var path=BranchRoutes.Plan(origin,NewGameWorld.Node(p.Authority!.Home.Value),VoyageExpense.PlanningExclusions(historical,actor,true),w:historical,departureAt:at+1);var legs=BranchRoutes.Schedule(origin,path,at+1,historical);long duration=legs[^1].EndAt-(at+1);
            int days=checked((int)Math.Max(2,(2L*(duration+1)+a.Input.DutySeconds+300+Day-1)/Day));Need(days<=7&&at+duration+a.Input.DutySeconds<until,"実在兵糧で往復と守備期間を確保できません");
            long kg=checked(100L*days*Day/MilitaryEconomy.PersonSecondsPerKg);var stock=CommunityEconomy.AccountAt(w,auth!.Home,at,rev);Need(MilitaryEconomy.CanMuster(w,auth.Home,at,rev)&&stock.HouseRice-HouseSalary.Reserved(w,auth.Home,at,rev)>=kg,"実米または支援人手が足りません");
            return new(a.Root,p.Input.Id,p.Input.Acceptance,actor,p.Input.Target,auth.Home,p.Input.Owner,p.Authority.Home,new("decision:defense-garrison/"+Hash(a.Root.Value)),100,a.Input.DutySeconds,days,until,at,rev,auth);
        }catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){reason=e.Message.Any(c=>c>127)?e.Message:"把握している陸路では出陣と帰還を組み立てられない";return null;}
    }
    static bool MustReturn(ContractWorld w,TreatyDefenseTerms t,long at,long rev)
    {
        if(at>t.Until||Cancelled(w,t.Root,at,rev)||!TreatyNegotiations.ClauseUsable(w,t.Commander,t.Agreement,TreatyClause.Defense,at,rev-1))return true;
        var arrival=Entries(w,at,rev).SingleOrDefault(e=>e.Root==t.Root&&e.Input.Action==TreatyDefenseAction.Arrive);if(arrival!=null)return at>=arrival.At+t.DutySeconds;
        var marches=w.NpcArmies!.Marches.Where(q=>q.Muster==t.Muster&&Before(q.At,q.Revision,at,rev)).ToArray();if(marches.Length==0)return false;
        var task=w.Tasks.Single(q=>q.RequestId==marches[0].Input.RequestId);return task.FinishedAt<=at&&(!Local(w,t.Commander,t.Destination,at,rev)||RegionalDomains.Owner(w,t.Destination)!=t.Recipient);
    }
    static TreatyDefenseEntry Prepare(ContractWorld w,TreatyDefenseInput i,EntityId actor,long at,long rev)
    {
        Need(RegionalDomains.Enabled(w)&&TreatyNegotiations.Enabled(w)&&NpcArmies.Enabled(w)&&MilitaryEconomy.Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action),"防衛援軍の実行を利用できません");
        EntityId root=i.Action==TreatyDefenseAction.Arrange?i.Id:i.Request;var es=Entries(w,at,rev);
        if(i.Action==TreatyDefenseAction.Arrange){var p=w.Treaties!.Operations.Single(p=>p.Input.Id==i.Request);Need(actor==w.PlayerControl&&p.Kind==TreatyOperation.RequestDefense&&p.Author==actor&&i.Original==null&&i.DutySeconds is >=60 and <=86400&&FactionStances.ResolveAuthority(w,actor,p.Input.Owner,at,rev-1)!=null&&TreatyNegotiations.ClauseUsable(w,actor,p.Input.Acceptance,TreatyClause.Defense,at,rev-1),"本人が知る防衛条項と実行手配権限が必要です");Need(w.Treaties.Operations.Any(q=>q.Kind==TreatyOperation.Acknowledge&&q.Input.Original==p.Input.Id&&w.Treaties.OperationOpenings.Any(o=>o.Message==q.Message&&o.Actor==actor&&Before(o.At,o.Revision,at,rev))),"受領返書を本人が開封してください");Need(!es.Any(e=>e.Input.Action==TreatyDefenseAction.Arrange&&e.Input.Request==i.Request),"同じ要請の実出陣は手配済みです");return new(i,root,actor,at,rev,null,PaperId(i.Id));}
        if(i.Action==TreatyDefenseAction.Resend){var old=State(w).Papers.Single(p=>p.Id==i.Original&&Before(p.At,p.Revision,at,rev));Need(i.DutySeconds==0&&i.Request==old.Root&&old.Sender==actor&&Failed(w,old,actor,at,rev)&&State(w).Papers.Count(p=>p.Root==old.Root&&p.Kind==old.Kind&&Before(p.At,p.Revision,at,rev))<3,"本人が不達を知った同じ書状だけ三通まで再送できます");Need(old.Kind!=TreatyDefensePaperKind.Ask||at<=old.Deadline,"元の出陣手配期限は延長できません");return new(i,old.Root,actor,at,rev,null,PaperId(i.Id));}
        Need(i.DutySeconds==0&&i.Original==null,"新しい守備条件は別の要請で指定します");var a=Arrange(w,root);var source=Aid(w,root);var t=Terms(w,root,at,rev);
        if(i.Action==TreatyDefenseAction.Cancel){Need(FactionStances.ResolveAuthority(w,actor,source.Input.Owner,at,rev-1)!=null,"援軍の取下げには現時点の代表権限が必要です");Need(actor==a.Actor&&!es.Any(e=>e.Root==root&&e.Input.Action==i.Action),"本人の未発送の取消だけ扱えます");return new(i,root,actor,at,rev,null,PaperId(i.Id));}
        Need(actor!=w.PlayerControl&&actor==source.Recipient&&!es.Any(e=>e.Root==root&&e.Input.Action==i.Action),"同じ軍の本人による一度限りの実行記録が必要です");
        if(i.Action is TreatyDefenseAction.Dispatch or TreatyDefenseAction.Refuse){Need(!es.Any(e=>e.Root==root&&e.Input.Action is TreatyDefenseAction.Dispatch or TreatyDefenseAction.Refuse)&&State(w).Papers.Any(p=>p.Root==root&&p.Kind==TreatyDefensePaperKind.Ask&&Opened(w,p.Id,actor,at,rev)),"本人開封した出陣手配が必要です");var candidate=Candidate(w,a,actor,at,rev,out var reason);Need((i.Action==TreatyDefenseAction.Dispatch)==(candidate!=null),"実在庫・兵数・権限・行程に基づく返答ではありません");return new(i,root,actor,at,rev,candidate,PaperId(i.Id)){Reason=reason};}
        Need(t!=null&&!w.NpcArmies!.Returns.Any(r=>r.Muster==t.Muster&&Before(r.At,r.Revision,at,rev)),"帰還済み、または元の出陣原本がありません");var terms=t!;Need(!ActiveTask(w,actor,at,rev),"現在の実移動が終わるまで待ってください");
        bool recalling=es.Any(e=>e.Root==root&&e.Input.Action==TreatyDefenseAction.Recall);
        if(i.Action==TreatyDefenseAction.Arrive)Need(!recalling&&!MustReturn(w,terms,at,rev)&&Local(w,actor,terms.Destination,at,rev)&&RegionalDomains.Owner(w,terms.Destination)==terms.Recipient,"守備先への現地到着を確認できません");
        else if(i.Action==TreatyDefenseAction.Recall)Need(!recalling&&MustReturn(w,terms,at,rev),"元の守備期間・本人受領した取消・現地状況からの帰還ではありません");
        else {Need(i.Action==TreatyDefenseAction.Return&&(recalling||MustReturn(w,terms,at,rev))&&Local(w,actor,terms.Source,at,rev),"軍が元の拠点へ実帰還していません");var receiver=HouseSuccession.Head(w,terms.Owner,at,rev-1);Need(RegionalDomains.Owner(w,terms.Source)==terms.Owner&&FactionStances.ResolveAuthority(w,receiver,terms.Owner,at,rev-1)!=null&&Local(w,receiver,terms.Source,at,rev),"現地の兵糧受領権者を確認できません");}
        return new(i,root,actor,at,rev,null,PaperId(i.Id));
    }
    static TreatyDefensePaper Paper(ContractWorld w,TreatyDefenseEntry e)
    {
        if(e.Input.Action==TreatyDefenseAction.Resend){var old=State(w).Papers.Single(p=>p.Id==e.Input.Original);return old with{Id=e.Paper,At=e.At,Revision=e.Revision,CopyOf=old.Id};}
        var a=e.Input.Action==TreatyDefenseAction.Arrange?e:Arrange(w,e.Root);var p=e.Input.Action==TreatyDefenseAction.Arrange?w.Treaties!.Operations.Single(p=>p.Input.Id==e.Input.Request):Aid(w,e.Root);var t=e.Terms??Terms(w,e.Root,e.At,e.Revision);if(e.Input.Action==TreatyDefenseAction.Cancel)t=State(w).Papers.LastOrDefault(q=>q.Root==e.Root&&q.Recipient==a.Actor&&Opened(w,q.Id,a.Actor,e.At,e.Revision))?.Terms;
        bool request=e.Input.Action is TreatyDefenseAction.Arrange or TreatyDefenseAction.Cancel;
        var kind=e.Input.Action switch{TreatyDefenseAction.Arrange=>TreatyDefensePaperKind.Ask,TreatyDefenseAction.Dispatch=>TreatyDefensePaperKind.Dispatched,TreatyDefenseAction.Refuse=>TreatyDefensePaperKind.Refused,TreatyDefenseAction.Arrive=>TreatyDefensePaperKind.Arrived,TreatyDefenseAction.Recall=>TreatyDefensePaperKind.Returning,TreatyDefenseAction.Return=>TreatyDefensePaperKind.Returned,_=>TreatyDefensePaperKind.Cancel};
        EntityId destination=request?(e.Input.Action==TreatyDefenseAction.Cancel&&t!=null?t.Destination:w.Treaties!.Operations.First(q=>q.Input.Acceptance==p.Input.Acceptance&&q.Author==p.Recipient).Authority!.Home):p.Authority!.Home;
        return new(e.Paper,kind,e.Root,e.Actor,request?p.Recipient:a.Actor,destination,e.At,e.Revision,Math.Min(a.At+14*Day,p.Terms.Until),t,e.At,null){Reason=e.Reason};
    }
    static MessageEnvelope Envelope(TreatyDefensePaper p)=>new(p.Id,p.Root.Value,Kind,p.Sender.Value,p.Recipient.Value,System.Text.Encoding.UTF8.GetString(ContractJson.Write(p)),p.Address.Value,p.At);
    internal static void Apply(ContractWorld w,TreatyDefenseInput i,EntityId actor){var e=Prepare(w,i,actor,w.ElapsedSeconds,w.CommitSequence);w.Treaties=w.Treaties! with{Defense=State(w) with{Entries=[..State(w).Entries,e]}};if(i.Action==TreatyDefenseAction.Dispatch)NpcArmies.Muster(w,e.Terms!.Muster,actor,e.Terms.Owner);if(i.Action==TreatyDefenseAction.Return)NpcArmies.Return(w,Terms(w,e.Root)!.Muster);var p=Paper(w,e);w.Treaties=w.Treaties! with{Defense=State(w) with{Papers=[..State(w).Papers,p]}};MessageFlow.Send(w.Messaging,Envelope(p),p.At,1);w.SealedMessages=[..w.SealedMessages,new(p.Id)];}
    static bool Failed(ContractWorld w,TreatyDefensePaper p,EntityId actor,long at,long rev)=>State(w).Failures.Any(o=>o.Actor==actor&&Before(o.At,o.Revision,at,rev)&&w.Messaging.Messages.Any(m=>m.Id==o.Message&&m.Kind=="delivery-failure"&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)));
    internal static void RecordOpening(ContractWorld w,EntityId actor,string id){if(w.Treaties?.Defense==null)return;var p=State(w).Papers.SingleOrDefault(p=>p.Id==id&&p.Recipient==actor);if(p!=null){if(!State(w).Openings.Any(o=>o.Message==id))w.Treaties=w.Treaties! with{Defense=State(w) with{Openings=[..State(w).Openings,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]}};return;}if(!State(w).Failures.Any(o=>o.Message==id)&&w.Messaging.Messages.Any(m=>m.Id==id&&m.Kind=="delivery-failure"&&m.RecipientId==actor.Value&&State(w).Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id))))w.Treaties=w.Treaties! with{Defense=State(w) with{Failures=[..State(w).Failures,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]}};}
    internal static void Update(ContractWorld w){if(w.Treaties?.Defense==null)return;foreach(var m in w.Messaging.Messages.Where(m=>m.Kind=="delivery-failure"&&State(w).Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id))).ToArray()){if(!w.SealedMessages.Contains(new(m.Id)))w.SealedMessages=[..w.SealedMessages,new(m.Id)];if(m.RecipientId!=w.PlayerControl.Value&&w.Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.ReceiverId==m.RecipientId&&a.Status==AttemptStatus.Delivered)){if(!MessageFlow.Knows(w.Messaging,m.Id,m.RecipientId))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(m.Id,m.RecipientId,w.ElapsedSeconds,m.Id)];RecordOpening(w,new(m.RecipientId),m.Id);}}foreach(var p in State(w).Papers.Where(p=>p.Recipient!=w.PlayerControl))if(w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==p.Recipient.Value&&a.Status==AttemptStatus.Delivered)){if(!MessageFlow.Knows(w.Messaging,p.Id,p.Recipient.Value))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(p.Id,p.Recipient.Value,w.ElapsedSeconds,p.Id)];RecordOpening(w,p.Recipient,p.Id);}}
    public static bool Can(ContractWorld w,TreatyDefenseInput i,EntityId actor){try{Prepare(w,i,actor,w.ElapsedSeconds,w.CommitSequence+1);return true;}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return false;}}
    internal static void TakeTurns(WorldSession session){if(!session.HasTreatyDefense())return;for(int n=0;n<32;n++){var w=session.DiagnosticSnapshot();bool acted=false;foreach(var a in State(w).Entries.Where(e=>e.Input.Action==TreatyDefenseAction.Arrange)){var root=a.Root;var source=Aid(w,root);var t=Terms(w,root);foreach(var action in t==null?new[]{TreatyDefenseAction.Dispatch,TreatyDefenseAction.Refuse}:new[]{TreatyDefenseAction.Return,TreatyDefenseAction.Arrive,TreatyDefenseAction.Recall}){var input=new TreatyDefenseInput(Auto(root,action),action,root);if(!OwnIdUsed(w,input.Id)&&Can(w,input,source.Recipient)){session.AutoTreatyDefense(input,source.Recipient);acted=true;break;}}if(acted)break;if(t==null||w.NpcArmies!.Returns.Any(q=>q.Muster==t.Muster)||ActiveTask(w,t.Commander,w.ElapsedSeconds,w.CommitSequence+1))continue;bool home=State(w).Entries.Any(e=>e.Root==root&&e.Input.Action==TreatyDefenseAction.Recall);var marches=w.NpcArmies.Marches.Where(q=>q.Muster==t.Muster).ToArray();if(!home&&marches.Length>0)continue;if(home&&Local(w,t.Commander,t.Source,w.ElapsedSeconds,w.CommitSequence+1))continue;try{var trip=NpcArmies.Move(w,t.Muster,"request:defense-trip/"+Hash(root.Value)+(home?"/home":"/out"),NewGameWorld.Node((home?t.Source:t.Destination).Value));if(session.Submit(trip,session.Revision).Code==ResultCode.Accepted){acted=true;break;}}catch(InvalidDataException){} }if(acted)continue;foreach(var p in State(w).Papers.Where(p=>p.Sender!=w.PlayerControl&&Failed(w,p,p.Sender,w.ElapsedSeconds,w.CommitSequence+1))){var i=new TreatyDefenseInput(new("request:defense-copy/"+Hash(p.Id)),TreatyDefenseAction.Resend,p.Root,Original:p.Id);if(!OwnIdUsed(w,i.Id)&&Can(w,i,p.Sender)){session.AutoTreatyDefense(i,p.Sender);acted=true;break;}}if(!acted)return;}}
    public static string? Address(ContractWorld w,MessageEnvelope m)=>State(w).Papers.SingleOrDefault(p=>p.Id==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
    public static TreatyDefenseCard[] View(ContractWorld w)=>State(w).Entries.Where(e=>e.Input.Action==TreatyDefenseAction.Arrange&&e.Actor==w.PlayerControl).Select(a=>{var p=State(w).Papers.LastOrDefault(p=>p.Root==a.Root&&p.Recipient==w.PlayerControl&&Opened(w,p.Id,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence+1));string status=p?.Kind switch{TreatyDefensePaperKind.Dispatched=>"出陣報告を開封・現在地は未確認",TreatyDefensePaperKind.Arrived=>"守備先への到着報告を開封",TreatyDefensePaperKind.Returning=>"帰還開始の報告を開封",TreatyDefensePaperKind.Returned=>"元の拠点への帰還報告を開封",TreatyDefensePaperKind.Refused=>"条件を満たせないとの辞退返書を開封",_=>"出陣手配発送・実行は未確認"};return new TreatyDefenseCard(a.Root,status,p?.Terms,p?.ObservedAt,Can(w,new(new("request:defense-preview"),TreatyDefenseAction.Cancel,a.Root),w.PlayerControl));}).ToArray();
    internal static IEnumerable<(long At,long Revision)> Inputs(ContractWorld w)=>State(w).Entries.Select(e=>(e.At,e.Revision)).Concat(State(w).Openings.Where(o=>o.Actor==w.PlayerControl).Select(o=>(o.At,o.Revision))).Concat(State(w).Failures.Where(o=>o.Actor==w.PlayerControl).Select(o=>(o.At,o.Revision)));
    internal static IEnumerable<long> Changes(ContractWorld w)=>State(w).Entries.Select(e=>e.At).Concat(State(w).Entries.Where(e=>e.Terms!=null).Select(e=>e.Terms!.Until+1)).Concat(State(w).Entries.Where(e=>e.Input.Action==TreatyDefenseAction.Arrive).Select(e=>e.At+Terms(w,e.Root)!.DutySeconds));
    internal static void Rewind(ContractWorld w,long at,long rev){if(w.Treaties?.Defense is {} s)w.Treaties=w.Treaties with{Defense=s.Entries.Any(e=>Before(e.At,e.Revision,at,rev+1))?s with{Entries=s.Entries.Where(e=>Before(e.At,e.Revision,at,rev+1)).ToArray(),Papers=s.Papers.Where(p=>Before(p.At,p.Revision,at,rev+1)).ToArray(),Openings=s.Openings.Where(o=>Before(o.At,o.Revision,at,rev+1)).ToArray(),Failures=s.Failures.Where(o=>Before(o.At,o.Revision,at,rev+1)).ToArray()}:null};}
    internal static void Validate(ContractWorld w){if(w.Treaties?.Defense is not {} s)return;Need(s.Schema==1&&s.Policy==Policy&&s.Entries!=null&&s.Papers!=null&&s.Openings!=null&&s.Failures!=null&&s.Entries.Select(e=>e.Input.Id).Distinct().Count()==s.Entries.Length,"援軍の実行原本が不正です");foreach(var e in s.Entries){Need(e.At<=w.ElapsedSeconds&&e.Revision>0&&e.Revision<=w.CommitSequence&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeTreatyDefense:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id)&&Prepare(w,e.Input,e.Actor,e.At,e.Revision)==e&&s.Papers.Contains(Paper(w,e)),"援軍の実兵・兵糧・現地行動と原本が一致しません");if(e.Terms is {} t){var m=NpcArmies.Musters(w).Single(m=>m.Id==t.Muster);Need(m.Owner==t.Owner&&m.Commander==t.Commander&&m.Site==t.Source&&m.At==e.At&&m.Revision==e.Revision&&m.Objective==null&&t.Soldiers==100&&t.CarryDays is >=2 and <=7,"防衛軍を複製または攻撃軍へ置換しています");}if(e.Input.Action==TreatyDefenseAction.Return)Need(w.NpcArmies!.Returns.Any(r=>r.Muster==Terms(w,e.Root)!.Muster&&r.At==e.At&&r.Revision==e.Revision),"軍の実帰還がありません");}Need(s.Papers.Select(p=>p.Id).Distinct().Count()==s.Papers.Length&&w.Messaging.Messages.Count(m=>m.Kind==Kind)==s.Papers.Length,"援軍封書が重複または欠落しています");foreach(var p in s.Papers){Need(w.Messaging.Messages.Contains(Envelope(p))&&w.SealedMessages.Contains(new(p.Id))&&MessageFlow.Knows(w.Messaging,p.Id,p.Recipient.Value)==s.Openings.Any(o=>o.Message==p.Id),"援軍書状の原文・封印・本人認識が違います");foreach(var c in w.Couriers!.Missions.Where(c=>w.Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==p.Id)))Need(c.Destination==NewGameWorld.Node(p.Address.Value),"援軍書状が相手の現在地を追尾しています");}Need(s.Openings.Select(o=>o.Message).Distinct().Count()==s.Openings.Length&&s.Failures.Select(o=>o.Message).Distinct().Count()==s.Failures.Length,"援軍の認識が重複しています");foreach(var o in s.Openings.Concat(s.Failures)){var m=w.Messaging.Messages.Single(m=>m.Id==o.Message);Need(m.RecipientId==o.Actor.Value&&o.At<=w.ElapsedSeconds&&o.Revision>0&&o.Revision<=w.CommitSequence&&MessageFlow.LearnedAt(w.Messaging,m.Id,o.Actor.Value)==o.At&&w.Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.ReceiverId==o.Actor.Value&&a.Status==AttemptStatus.Delivered&&a.FinishedAt<=o.At),"援軍原本または不達の本人開封ではありません");if(s.Failures.Contains(o))Need(m.Kind=="delivery-failure"&&s.Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)),"別の不達を混在させています");else Need(s.Papers.Any(p=>p.Id==m.Id&&p.Revision<o.Revision),"援軍書状の開封順序が不正です");}}
}

public sealed partial class WorldSession
{
    internal bool HasTreatyDefense(){lock(gate)return state.Treaties?.Defense!=null;}
    internal void AutoTreatyDefense(TreatyDefenseInput i,EntityId actor){lock(gate){if(actor==state.PlayerControl||i.Action is TreatyDefenseAction.Arrange or TreatyDefenseAction.Cancel)throw new InvalidDataException("本人の署名を自動操作しません");Change(w=>TreatyDefense.Apply(w,i,actor));}}
    public CommandResult ManageTreatyDefense(TreatyDefenseInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||i.Action is not(TreatyDefenseAction.Arrange or TreatyDefenseAction.Cancel or TreatyDefenseAction.Resend))return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"本人の出陣手配ではありません");var old=state.Treaties?.Defense?.Entries.SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の操作の原本です");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>TreatyDefense.Apply(w,i,actor));TreatyDefense.TakeTurns(this);return new(ResultCode.Accepted,i.Id,state.CommitSequence,"防衛援軍の書状を発送しました。出陣・到着は報告で確認します");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
